INSERT INTO Authors (Name, Description, ImageUrl, CreatedAt, UpdatedAt) VALUES
  ('Agatha Christie', 'English crime writer (1890–1976), often called the Queen of Crime. She wrote 66 detective novels and created Hercule Poirot and Miss Marple.', 'https://covers.openlibrary.org/a/olid/OL27695A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Aldous Huxley', 'English novelist and essayist (1894–1963), best known for Brave New World and for his writing on society, science and the mind.', 'https://covers.openlibrary.org/a/olid/OL19767A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Alex Michaelides', 'British-Cypriot novelist and screenwriter. His debut thriller The Silent Patient became an international bestseller.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Andrew Hunt', 'American programmer and author, co-writer of The Pragmatic Programmer and one of the original signatories of the Agile Manifesto.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Andy Weir', 'American novelist and former software engineer. He first published The Martian chapter by chapter on his own website.', 'https://covers.openlibrary.org/a/olid/OL7234434A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Cal Newport', 'American computer science professor at Georgetown University who writes about focus, technology and working well.', 'https://covers.openlibrary.org/a/olid/OL2853212A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Charles Duhigg', 'American journalist and Pulitzer prize-winning reporter who writes about habits, productivity and communication.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Charlotte Brontë', 'English novelist (1816–1855), the eldest of the three Brontë sisters. Jane Eyre, published under the name Currer Bell, was an immediate success.', 'https://covers.openlibrary.org/a/olid/OL113362A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Dale Carnegie', 'American writer and lecturer (1888–1955) whose courses and books on public speaking and dealing with people have been read for generations.', 'https://covers.openlibrary.org/a/olid/OL107569A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Dan Brown', 'American thriller writer best known for the Robert Langdon novels, which mix art, history, codes and conspiracy.', 'https://covers.openlibrary.org/a/olid/OL39307A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Daniel Kahneman', 'Israeli-American psychologist (1934–2024) who won the Nobel prize in economics for his work on judgement and decision-making.', 'https://covers.openlibrary.org/a/olid/OL2066695A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Delia Owens', 'American zoologist and author who spent years studying wildlife in Africa before writing her first novel, Where the Crawdads Sing.', 'https://covers.openlibrary.org/a/olid/OL832711A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Douglas Adams', 'English writer and humorist (1952–2001). The Hitchhiker''s Guide to the Galaxy began as a radio comedy before becoming a series of novels.', 'https://covers.openlibrary.org/a/olid/OL272947A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Emily Brontë', 'English novelist and poet (1818–1848). Wuthering Heights, her only novel, was published a year before her death.', 'https://covers.openlibrary.org/a/olid/OL24529A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Erich Gamma', 'Swiss computer scientist, one of the four authors of Design Patterns and a lead developer of widely used programming tools.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('F. Scott Fitzgerald', 'American novelist (1896–1940) and chronicler of the Jazz Age, remembered above all for The Great Gatsby.', 'https://covers.openlibrary.org/a/olid/OL27349A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Frank Herbert', 'American science fiction writer (1920–1986). Dune, which grew out of his research into desert ecology, became one of the best-selling novels in the genre.', 'https://covers.openlibrary.org/a/olid/OL79034A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Gene Kim', 'American author and researcher who studies high-performing technology organisations and helped popularise DevOps.', 'https://covers.openlibrary.org/a/olid/OL3030720A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('George Orwell', 'Pen name of Eric Arthur Blair (1903–1950), English novelist, essayist and journalist known for clear prose and for his opposition to totalitarianism.', 'https://covers.openlibrary.org/a/olid/OL118077A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('George R.R. Martin', 'American novelist and screenwriter, author of the epic fantasy series A Song of Ice and Fire, adapted for television as Game of Thrones.', 'https://covers.openlibrary.org/a/olid/OL234664A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Gillian Flynn', 'American novelist and screenwriter, and a former television critic, known for dark psychological thrillers.', 'https://covers.openlibrary.org/a/olid/OL1433006A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Harper Lee', 'American novelist (1926–2016). To Kill a Mockingbird, drawn from her Alabama childhood, won the Pulitzer prize in 1961.', 'https://covers.openlibrary.org/a/olid/OL498120A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Isaac Asimov', 'Russian-born American writer and professor of biochemistry (1920–1992), who wrote or edited about 500 books, including the Foundation and Robot series.', 'https://covers.openlibrary.org/a/olid/OL34221A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('J.D. Salinger', 'American writer (1919–2010) who became famous for The Catcher in the Rye and spent most of his later life out of public view.', 'https://covers.openlibrary.org/a/olid/OL540486A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('J.K. Rowling', 'British author of the Harry Potter series, one of the best-selling book series in history. She also writes crime novels as Robert Galbraith.', 'https://covers.openlibrary.org/a/olid/OL23919A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('J.R.R. Tolkien', 'English writer and Oxford professor of language (1892–1973). He created Middle-earth, the setting of The Hobbit and The Lord of the Rings.', 'https://covers.openlibrary.org/a/olid/OL26320A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('James Clear', 'American writer and speaker on habits, decision-making and continuous improvement.', 'https://covers.openlibrary.org/a/olid/OL7422948A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Jane Austen', 'English novelist (1775–1817) whose six novels, full of wit and close observation of social life, are among the most loved in the language.', 'https://covers.openlibrary.org/a/olid/OL21594A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Khaled Hosseini', 'Afghan-American novelist and former doctor. His novels, set largely in Afghanistan, have sold tens of millions of copies.', 'https://covers.openlibrary.org/a/olid/OL1412764A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Markus Zusak', 'Australian writer best known for The Book Thief, which has been translated into more than sixty languages.', 'https://covers.openlibrary.org/a/olid/OL1425869A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Martin Fowler', 'British software developer, author and speaker who writes about software design, refactoring and agile methods.', 'https://covers.openlibrary.org/a/olid/OL27090A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Martin Kleppmann', 'Researcher in distributed systems at the University of Cambridge, and previously a software engineer and entrepreneur.', 'https://covers.openlibrary.org/a/olid/OL7477772A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Matt Haig', 'English author of novels and non-fiction for adults and children, often drawing on his own experience of mental health.', 'https://covers.openlibrary.org/a/olid/OL1416857A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Michelle Obama', 'American lawyer and writer who was First Lady of the United States from 2009 to 2017.', 'https://covers.openlibrary.org/a/olid/OL7119254A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Morgan Housel', 'American writer on finance and investing, and a partner at a venture capital firm.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Neil Gaiman', 'English author of novels, comics and children''s books, including The Sandman, American Gods and Coraline.', 'https://covers.openlibrary.org/a/olid/OL53305A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Orson Scott Card', 'American writer best known for science fiction. Ender''s Game and its sequel both won the Hugo and Nebula awards.', 'https://covers.openlibrary.org/a/olid/OL25161A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Patrick Rothfuss', 'American fantasy writer, author of The Kingkiller Chronicle, which begins with The Name of the Wind.', 'https://covers.openlibrary.org/a/olid/OL2830895A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Paulo Coelho', 'Brazilian novelist and one of the most widely read authors in the world. The Alchemist has been translated into more than eighty languages.', 'https://covers.openlibrary.org/a/olid/OL66700A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Ray Bradbury', 'American writer (1920–2012) of science fiction, fantasy and horror, celebrated for Fahrenheit 451 and The Martian Chronicles.', 'https://covers.openlibrary.org/a/olid/OL24137A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Rebecca Skloot', 'American science writer. The Immortal Life of Henrietta Lacks, her first book, took more than a decade to research and write.', 'https://covers.openlibrary.org/a/olid/OL6720423A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Robert C. Martin', 'American software engineer and author, widely known as Uncle Bob, who has written extensively on clean code and software design.', 'https://covers.openlibrary.org/a/olid/OL2653686A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Sally Rooney', 'Irish novelist whose books about young people, class and relationships have been widely acclaimed and adapted for television.', 'https://covers.openlibrary.org/a/olid/OL7919580A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Shehan Karunatilaka', 'Sri Lankan writer. He won the Booker prize in 2022 for The Seven Moons of Maali Almeida.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Stephen Hawking', 'English theoretical physicist and cosmologist (1942–2018) who made major contributions to the study of black holes and brought science to a wide audience.', 'https://covers.openlibrary.org/a/olid/OL2675573A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Stephen King', 'American author of horror, suspense and fantasy, with more than sixty novels to his name, many of them adapted for film and television.', 'https://covers.openlibrary.org/a/olid/OL19981A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Stephen R. Covey', 'American educator, author and businessman (1932–2012), best known for The 7 Habits of Highly Effective People.', 'https://covers.openlibrary.org/a/olid/OL383159A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Stieg Larsson', 'Swedish journalist and writer (1954–2004). His Millennium trilogy of crime novels was published after his death.', 'https://covers.openlibrary.org/a/olid/OL1414302A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Tara Westover', 'American memoirist and historian who earned a doctorate from Cambridge after a childhood without formal schooling.', 'https://covers.openlibrary.org/a/olid/OL7421324A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Thomas H. Cormen', 'American computer scientist and professor emeritus at Dartmouth College, co-author of the standard textbook Introduction to Algorithms.', NULL, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('William Gibson', 'American-Canadian writer who coined the word cyberspace and helped found the cyberpunk genre.', 'https://covers.openlibrary.org/a/olid/OL26283A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Yann Martel', 'Canadian author who won the Booker prize in 2002 for Life of Pi.', 'https://covers.openlibrary.org/a/olid/OL422052A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP()),
  ('Yuval Noah Harari', 'Israeli historian and professor at the Hebrew University of Jerusalem who writes about the past and future of humankind.', 'https://covers.openlibrary.org/a/olid/OL3778242A-L.jpg?default=false', UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO Books (Title, Author, ISBN, Genre, CoverImageUrl, Description, TotalCopies, AvailableCopies, CreatedAt, UpdatedAt) VALUES
  ('Pride and Prejudice', 'Jane Austen', '9780141439518', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141439518-L.jpg?default=false', 'Elizabeth Bennet has no intention of marrying for money, and even less of liking the proud Mr Darcy. A sharp, funny novel about first impressions, family pressure and learning to change your mind.', 4, 4, UTC_TIMESTAMP() - INTERVAL 0 MINUTE, UTC_TIMESTAMP() - INTERVAL 0 MINUTE),
  ('Emma', 'Jane Austen', '9780141439587', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141439587-L.jpg?default=false', 'Emma Woodhouse is clever, rich and certain she knows who should marry whom. Her matchmaking goes wrong in every direction, and she slowly discovers how little she understood, including her own heart.', 2, 2, UTC_TIMESTAMP() - INTERVAL 37 MINUTE, UTC_TIMESTAMP() - INTERVAL 37 MINUTE),
  ('Sense and Sensibility', 'Jane Austen', '9780141439662', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141439662-L.jpg?default=false', 'When their father dies, the Dashwood sisters lose their home and their prospects. Cautious Elinor and impulsive Marianne each fall in love, and each learns something from the other''s way of facing disappointment.', 2, 2, UTC_TIMESTAMP() - INTERVAL 3 MINUTE, UTC_TIMESTAMP() - INTERVAL 3 MINUTE),
  ('Persuasion', 'Jane Austen', '9780141439686', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141439686-L.jpg?default=false', 'Eight years ago Anne Elliot was talked out of marrying a young naval officer with no fortune. Now he is back, successful and still unmarried, in Jane Austen''s quietest and most grown-up love story.', 1, 1, UTC_TIMESTAMP() - INTERVAL 40 MINUTE, UTC_TIMESTAMP() - INTERVAL 40 MINUTE),
  ('Nineteen Eighty-Four', 'George Orwell', '9780451524935', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780451524935-L.jpg?default=false', 'In a state that watches every citizen and rewrites the past daily, Winston Smith begins to keep a secret diary. A chilling novel about surveillance, propaganda and what it costs to think for yourself.', 5, 5, UTC_TIMESTAMP() - INTERVAL 6 MINUTE, UTC_TIMESTAMP() - INTERVAL 6 MINUTE),
  ('Animal Farm', 'George Orwell', '9780451526342', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780451526342-L.jpg?default=false', 'The animals of Manor Farm drive out their farmer and set out to run things as equals. Then the pigs take charge. A short, biting fable about how revolutions are betrayed.', 4, 4, UTC_TIMESTAMP() - INTERVAL 43 MINUTE, UTC_TIMESTAMP() - INTERVAL 43 MINUTE),
  ('To Kill a Mockingbird', 'Harper Lee', '9780061120084', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780061120084-L.jpg?default=false', 'In a small Alabama town in the 1930s, lawyer Atticus Finch defends a Black man falsely accused of a crime. His daughter Scout tells the story of a childhood shaped by prejudice, courage and conscience.', 4, 4, UTC_TIMESTAMP() - INTERVAL 9 MINUTE, UTC_TIMESTAMP() - INTERVAL 9 MINUTE),
  ('The Great Gatsby', 'F. Scott Fitzgerald', '9780743273565', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780743273565-L.jpg?default=false', 'Jay Gatsby throws the most lavish parties on Long Island, all in the hope that one particular guest will come. A glittering, melancholy portrait of wealth and longing in 1920s America.', 3, 3, UTC_TIMESTAMP() - INTERVAL 46 MINUTE, UTC_TIMESTAMP() - INTERVAL 46 MINUTE),
  ('Jane Eyre', 'Charlotte Brontë', '9780141441146', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141441146-L.jpg?default=false', 'An orphan with a fierce sense of her own worth becomes governess at Thornfield Hall and falls for its brooding master. But the house holds a secret that will test everything she believes in.', 2, 2, UTC_TIMESTAMP() - INTERVAL 12 MINUTE, UTC_TIMESTAMP() - INTERVAL 12 MINUTE),
  ('Wuthering Heights', 'Emily Brontë', '9780141439556', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780141439556-L.jpg?default=false', 'On the Yorkshire moors, the bond between Catherine Earnshaw and the foundling Heathcliff turns into an obsession that wrecks two families. A wild, dark story of love and revenge across two generations.', 2, 2, UTC_TIMESTAMP() - INTERVAL 49 MINUTE, UTC_TIMESTAMP() - INTERVAL 49 MINUTE),
  ('The Catcher in the Rye', 'J.D. Salinger', '9780316769488', 'Classics', 'https://covers.openlibrary.org/b/isbn/9780316769488-L.jpg?default=false', 'Expelled from yet another school, sixteen-year-old Holden Caulfield wanders New York for a few days before facing his parents. His restless, funny, wounded voice made this a classic of growing up.', 3, 3, UTC_TIMESTAMP() - INTERVAL 15 MINUTE, UTC_TIMESTAMP() - INTERVAL 15 MINUTE),
  ('The Hobbit', 'J.R.R. Tolkien', '9780547928227', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780547928227-L.jpg?default=false', 'Bilbo Baggins likes his armchair and his second breakfast, until a wizard and thirteen dwarves sweep him off to win back a dragon''s treasure. The adventure that opens the door to Middle-earth.', 5, 5, UTC_TIMESTAMP() - INTERVAL 52 MINUTE, UTC_TIMESTAMP() - INTERVAL 52 MINUTE),
  ('The Fellowship of the Ring', 'J.R.R. Tolkien', '9780547928210', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780547928210-L.jpg?default=false', 'Frodo Baggins inherits a ring that turns out to be the most dangerous object in the world. With eight companions he sets out to destroy it, in the first part of The Lord of the Rings.', 3, 3, UTC_TIMESTAMP() - INTERVAL 18 MINUTE, UTC_TIMESTAMP() - INTERVAL 18 MINUTE),
  ('The Two Towers', 'J.R.R. Tolkien', '9780547928203', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780547928203-L.jpg?default=false', 'The Fellowship is scattered. While Frodo and Sam press on towards Mordor with an unreliable guide, their friends are drawn into the war for Rohan. The second part of The Lord of the Rings.', 3, 3, UTC_TIMESTAMP() - INTERVAL 55 MINUTE, UTC_TIMESTAMP() - INTERVAL 55 MINUTE),
  ('The Return of the King', 'J.R.R. Tolkien', '9780547928197', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780547928197-L.jpg?default=false', 'As the armies of the West make a last stand, two hobbits climb the slopes of Mount Doom. The final part of The Lord of the Rings brings the quest, and an age, to its end.', 3, 3, UTC_TIMESTAMP() - INTERVAL 21 MINUTE, UTC_TIMESTAMP() - INTERVAL 21 MINUTE),
  ('Harry Potter and the Sorcerer''s Stone', 'J.K. Rowling', '9780590353427', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780590353427-L.jpg?default=false', 'On his eleventh birthday Harry Potter learns that he is a wizard, and that a place is waiting for him at Hogwarts School of Witchcraft and Wizardry. The start of the series.', 6, 6, UTC_TIMESTAMP() - INTERVAL 58 MINUTE, UTC_TIMESTAMP() - INTERVAL 58 MINUTE),
  ('Harry Potter and the Chamber of Secrets', 'J.K. Rowling', '9780439064873', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780439064873-L.jpg?default=false', 'Harry''s second year at Hogwarts is interrupted by warnings written on the walls and students found turned to stone. Someone has opened the Chamber of Secrets.', 4, 4, UTC_TIMESTAMP() - INTERVAL 24 MINUTE, UTC_TIMESTAMP() - INTERVAL 24 MINUTE),
  ('Harry Potter and the Prisoner of Azkaban', 'J.K. Rowling', '9780439136365', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780439136365-L.jpg?default=false', 'A notorious prisoner has escaped from the wizard jail of Azkaban, and everyone believes he is coming for Harry. The third book, and the one where the story grows darker.', 4, 4, UTC_TIMESTAMP() - INTERVAL 61 MINUTE, UTC_TIMESTAMP() - INTERVAL 61 MINUTE),
  ('Harry Potter and the Goblet of Fire', 'J.K. Rowling', '9780439139601', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780439139601-L.jpg?default=false', 'Hogwarts hosts a dangerous tournament between three schools, and Harry''s name comes out of the goblet although he never entered. The fourth book ends with a return that changes everything.', 3, 3, UTC_TIMESTAMP() - INTERVAL 27 MINUTE, UTC_TIMESTAMP() - INTERVAL 27 MINUTE),
  ('A Game of Thrones', 'George R.R. Martin', '9780553593716', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780553593716-L.jpg?default=false', 'Noble families scheme for the Iron Throne of the Seven Kingdoms while an older threat stirs in the frozen north. The first volume of A Song of Ice and Fire.', 3, 3, UTC_TIMESTAMP() - INTERVAL 64 MINUTE, UTC_TIMESTAMP() - INTERVAL 64 MINUTE),
  ('The Name of the Wind', 'Patrick Rothfuss', '9780756404741', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780756404741-L.jpg?default=false', 'Kvothe, an innkeeper with a hidden past, agrees to tell the true story behind his own legend: a gifted child of travelling players who became the most notorious wizard of his age.', 2, 2, UTC_TIMESTAMP() - INTERVAL 30 MINUTE, UTC_TIMESTAMP() - INTERVAL 30 MINUTE),
  ('American Gods', 'Neil Gaiman', '9780062572233', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780062572233-L.jpg?default=false', 'Released from prison, Shadow takes a job with the mysterious Mr Wednesday and finds himself in a war between the old gods brought to America by immigrants and the new gods of technology and media.', 2, 2, UTC_TIMESTAMP() - INTERVAL 67 MINUTE, UTC_TIMESTAMP() - INTERVAL 67 MINUTE),
  ('Coraline', 'Neil Gaiman', '9780380807345', 'Fantasy', 'https://covers.openlibrary.org/b/isbn/9780380807345-L.jpg?default=false', 'Behind a locked door in her new flat, Coraline finds another home with another mother who wants her to stay for ever. A short, properly frightening tale about being brave.', 2, 2, UTC_TIMESTAMP() - INTERVAL 33 MINUTE, UTC_TIMESTAMP() - INTERVAL 33 MINUTE),
  ('Dune', 'Frank Herbert', '9780441172719', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780441172719-L.jpg?default=false', 'On the desert planet Arrakis, the only source of the most valuable substance in the universe, young Paul Atreides is caught in a plot that destroys his family. A landmark of science fiction about power, ecology and prophecy.', 4, 4, UTC_TIMESTAMP() - INTERVAL 70 MINUTE, UTC_TIMESTAMP() - INTERVAL 70 MINUTE),
  ('Foundation', 'Isaac Asimov', '9780553293357', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780553293357-L.jpg?default=false', 'A mathematician predicts the fall of the Galactic Empire and thirty thousand years of chaos to follow. He sets up a small colony of scholars with a plan to shorten the dark age to one thousand.', 3, 3, UTC_TIMESTAMP() - INTERVAL 36 MINUTE, UTC_TIMESTAMP() - INTERVAL 36 MINUTE),
  ('I, Robot', 'Isaac Asimov', '9780553382563', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780553382563-L.jpg?default=false', 'Nine linked stories follow the development of robots bound by the Three Laws of Robotics, and the unexpected ways those laws can go wrong. The book that shaped how we imagine thinking machines.', 2, 2, UTC_TIMESTAMP() - INTERVAL 2 MINUTE, UTC_TIMESTAMP() - INTERVAL 2 MINUTE),
  ('Ender''s Game', 'Orson Scott Card', '9780812550702', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780812550702-L.jpg?default=false', 'Earth is preparing for an alien invasion by training children as commanders. Ender Wiggin is the most promising of them all, and the games he is made to play are not what they seem.', 3, 3, UTC_TIMESTAMP() - INTERVAL 39 MINUTE, UTC_TIMESTAMP() - INTERVAL 39 MINUTE),
  ('The Hitchhiker''s Guide to the Galaxy', 'Douglas Adams', '9780345391803', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780345391803-L.jpg?default=false', 'Seconds before Earth is demolished to make way for a bypass, Arthur Dent is rescued by a friend who turns out to be an alien. A gloriously silly journey through space. Don''t panic.', 4, 4, UTC_TIMESTAMP() - INTERVAL 5 MINUTE, UTC_TIMESTAMP() - INTERVAL 5 MINUTE),
  ('Fahrenheit 451', 'Ray Bradbury', '9781451673319', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9781451673319-L.jpg?default=false', 'Guy Montag is a fireman, and his job is to burn books. Then he meets a neighbour who asks whether he is happy, and he begins to wonder what is inside the things he destroys.', 3, 3, UTC_TIMESTAMP() - INTERVAL 42 MINUTE, UTC_TIMESTAMP() - INTERVAL 42 MINUTE),
  ('Brave New World', 'Aldous Huxley', '9780060850524', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780060850524-L.jpg?default=false', 'In the World State everyone is engineered for their place in society and kept content with pleasure and a drug called soma. Then an outsider arrives who has grown up with Shakespeare instead.', 3, 3, UTC_TIMESTAMP() - INTERVAL 8 MINUTE, UTC_TIMESTAMP() - INTERVAL 8 MINUTE),
  ('The Martian', 'Andy Weir', '9780553418026', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780553418026-L.jpg?default=false', 'A dust storm forces his crew to leave Mars without him. Astronaut Mark Watney has to stay alive on a dead planet with limited supplies, a lot of ingenuity and a stubborn sense of humour.', 3, 3, UTC_TIMESTAMP() - INTERVAL 45 MINUTE, UTC_TIMESTAMP() - INTERVAL 45 MINUTE),
  ('Project Hail Mary', 'Andy Weir', '9780593135204', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780593135204-L.jpg?default=false', 'A man wakes on a spacecraft with no memory of who he is or why he is there. Bit by bit he works out that he is humanity''s last chance, and that he is not entirely alone.', 2, 0, UTC_TIMESTAMP() - INTERVAL 11 MINUTE, UTC_TIMESTAMP() - INTERVAL 11 MINUTE),
  ('Neuromancer', 'William Gibson', '9780441569595', 'Science Fiction', 'https://covers.openlibrary.org/b/isbn/9780441569595-L.jpg?default=false', 'Case was the best data thief in the business until his employers ruined his nervous system. Now a mysterious patron offers a cure in exchange for one impossible job. The novel that defined cyberpunk.', 1, 0, UTC_TIMESTAMP() - INTERVAL 48 MINUTE, UTC_TIMESTAMP() - INTERVAL 48 MINUTE),
  ('Murder on the Orient Express', 'Agatha Christie', '9780062693662', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780062693662-L.jpg?default=false', 'The famous train is stopped by snow in the middle of the night, and a passenger lies dead in his locked compartment. Hercule Poirot is on board, and so is the murderer.', 3, 3, UTC_TIMESTAMP() - INTERVAL 14 MINUTE, UTC_TIMESTAMP() - INTERVAL 14 MINUTE),
  ('And Then There Were None', 'Agatha Christie', '9780062073488', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780062073488-L.jpg?default=false', 'Ten strangers are invited to an island off the Devon coast. Their host never appears, and one by one the guests begin to die. Agatha Christie''s most ingenious puzzle.', 3, 3, UTC_TIMESTAMP() - INTERVAL 51 MINUTE, UTC_TIMESTAMP() - INTERVAL 51 MINUTE),
  ('The Murder of Roger Ackroyd', 'Agatha Christie', '9780062073563', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780062073563-L.jpg?default=false', 'A wealthy man is stabbed in his study in a quiet English village, and the recently retired Hercule Poirot agrees to investigate. Famous for one of the most daring endings in crime fiction.', 2, 2, UTC_TIMESTAMP() - INTERVAL 17 MINUTE, UTC_TIMESTAMP() - INTERVAL 17 MINUTE),
  ('Death on the Nile', 'Agatha Christie', '9780062073556', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780062073556-L.jpg?default=false', 'A young heiress is shot on a Nile steamer during her honeymoon. Nearly everyone on board had a reason to hate her, and Hercule Poirot happens to be among the passengers.', 2, 2, UTC_TIMESTAMP() - INTERVAL 54 MINUTE, UTC_TIMESTAMP() - INTERVAL 54 MINUTE),
  ('The Girl with the Dragon Tattoo', 'Stieg Larsson', '9780307454546', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780307454546-L.jpg?default=false', 'A disgraced journalist is hired to look into the disappearance of a girl forty years ago. He is joined by Lisbeth Salander, a brilliant and troubled hacker, and what they uncover is far worse than a missing person.', 3, 3, UTC_TIMESTAMP() - INTERVAL 20 MINUTE, UTC_TIMESTAMP() - INTERVAL 20 MINUTE),
  ('Gone Girl', 'Gillian Flynn', '9780307588371', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780307588371-L.jpg?default=false', 'On their fifth wedding anniversary Amy Dunne vanishes, and her husband Nick becomes the obvious suspect. Told by both of them in turn, and neither is telling the whole truth.', 3, 3, UTC_TIMESTAMP() - INTERVAL 57 MINUTE, UTC_TIMESTAMP() - INTERVAL 57 MINUTE),
  ('The Da Vinci Code', 'Dan Brown', '9780307474278', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780307474278-L.jpg?default=false', 'A murder in the Louvre leaves a trail of clues hidden in the works of Leonardo. Symbologist Robert Langdon follows them across Europe with a secret society and the police close behind.', 4, 4, UTC_TIMESTAMP() - INTERVAL 23 MINUTE, UTC_TIMESTAMP() - INTERVAL 23 MINUTE),
  ('The Silent Patient', 'Alex Michaelides', '9781250301697', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9781250301697-L.jpg?default=false', 'A celebrated painter shoots her husband and then never speaks again. A psychotherapist becomes determined to find out why, and his search takes him somewhere he did not expect.', 2, 2, UTC_TIMESTAMP() - INTERVAL 60 MINUTE, UTC_TIMESTAMP() - INTERVAL 60 MINUTE),
  ('The Shining', 'Stephen King', '9780307743657', 'Mystery & Thriller', 'https://covers.openlibrary.org/b/isbn/9780307743657-L.jpg?default=false', 'Jack Torrance takes a job as winter caretaker of the remote Overlook Hotel, hoping for a fresh start with his wife and young son. The hotel has other plans for the family.', 2, 2, UTC_TIMESTAMP() - INTERVAL 26 MINUTE, UTC_TIMESTAMP() - INTERVAL 26 MINUTE),
  ('Sapiens: A Brief History of Humankind', 'Yuval Noah Harari', '9780062316097', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9780062316097-L.jpg?default=false', 'How did one species of ape come to run the planet? A sweeping account of human history, from the first stories we told one another to the age of money, empire and science.', 4, 4, UTC_TIMESTAMP() - INTERVAL 63 MINUTE, UTC_TIMESTAMP() - INTERVAL 63 MINUTE),
  ('Homo Deus', 'Yuval Noah Harari', '9780062464316', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9780062464316-L.jpg?default=false', 'Having largely tamed famine, plague and war, what will humanity aim for next? A provocative look at the future, where data, biotechnology and artificial intelligence may reshape what being human means.', 2, 2, UTC_TIMESTAMP() - INTERVAL 29 MINUTE, UTC_TIMESTAMP() - INTERVAL 29 MINUTE),
  ('Educated', 'Tara Westover', '9780399590504', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9780399590504-L.jpg?default=false', 'Tara Westover grew up in a survivalist family in rural Idaho and never set foot in a classroom until she was seventeen. Her memoir follows her path to a Cambridge doctorate and what it cost her at home.', 3, 3, UTC_TIMESTAMP() - INTERVAL 66 MINUTE, UTC_TIMESTAMP() - INTERVAL 66 MINUTE),
  ('Becoming', 'Michelle Obama', '9781524763138', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9781524763138-L.jpg?default=false', 'Michelle Obama tells her own story, from a childhood on the South Side of Chicago through her career as a lawyer to eight years in the White House. Warm, candid and reflective.', 3, 3, UTC_TIMESTAMP() - INTERVAL 32 MINUTE, UTC_TIMESTAMP() - INTERVAL 32 MINUTE),
  ('A Brief History of Time', 'Stephen Hawking', '9780553380163', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9780553380163-L.jpg?default=false', 'Where did the universe come from, and how might it end? Stephen Hawking explains the big bang, black holes and the nature of time for readers with no background in physics.', 2, 2, UTC_TIMESTAMP() - INTERVAL 69 MINUTE, UTC_TIMESTAMP() - INTERVAL 69 MINUTE),
  ('Thinking, Fast and Slow', 'Daniel Kahneman', '9780374533557', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9780374533557-L.jpg?default=false', 'A Nobel prize-winning psychologist describes the two systems that drive how we think: one fast and intuitive, one slow and deliberate. A guide to the mistakes our minds make and how to spot them.', 3, 3, UTC_TIMESTAMP() - INTERVAL 35 MINUTE, UTC_TIMESTAMP() - INTERVAL 35 MINUTE),
  ('The Immortal Life of Henrietta Lacks', 'Rebecca Skloot', '9781400052189', 'Non-fiction', 'https://covers.openlibrary.org/b/isbn/9781400052189-L.jpg?default=false', 'In 1951 cells were taken from a poor Black tobacco farmer without her knowledge. They became one of the most important tools in medicine. This is her story, and her family''s.', 2, 2, UTC_TIMESTAMP() - INTERVAL 1 MINUTE, UTC_TIMESTAMP() - INTERVAL 1 MINUTE),
  ('Atomic Habits', 'James Clear', '9780735211292', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9780735211292-L.jpg?default=false', 'Small changes, repeated daily, add up to remarkable results. A practical guide to building good habits and breaking bad ones by changing your surroundings and routines rather than relying on willpower.', 5, 5, UTC_TIMESTAMP() - INTERVAL 38 MINUTE, UTC_TIMESTAMP() - INTERVAL 38 MINUTE),
  ('The Psychology of Money', 'Morgan Housel', '9780857197689', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9780857197689-L.jpg?default=false', 'Doing well with money has less to do with what you know than with how you behave. Nineteen short chapters on the odd ways people think about wealth, risk and happiness.', 3, 3, UTC_TIMESTAMP() - INTERVAL 4 MINUTE, UTC_TIMESTAMP() - INTERVAL 4 MINUTE),
  ('Deep Work', 'Cal Newport', '9781455586691', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9781455586691-L.jpg?default=false', 'The ability to concentrate without distraction is becoming rare just as it becomes more valuable. Cal Newport makes the case for focused work and offers rules for protecting it.', 2, 2, UTC_TIMESTAMP() - INTERVAL 41 MINUTE, UTC_TIMESTAMP() - INTERVAL 41 MINUTE),
  ('The 7 Habits of Highly Effective People', 'Stephen R. Covey', '9781982137274', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9781982137274-L.jpg?default=false', 'One of the most influential books on personal effectiveness. Covey sets out seven habits, built on principles such as responsibility and integrity, for working and living well with other people.', 3, 3, UTC_TIMESTAMP() - INTERVAL 7 MINUTE, UTC_TIMESTAMP() - INTERVAL 7 MINUTE),
  ('How to Win Friends and Influence People', 'Dale Carnegie', '9780671027032', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9780671027032-L.jpg?default=false', 'First published in 1936 and still widely read, this is a plain-spoken guide to getting along with people: listening properly, showing genuine interest and winning others to your way of thinking.', 3, 3, UTC_TIMESTAMP() - INTERVAL 44 MINUTE, UTC_TIMESTAMP() - INTERVAL 44 MINUTE),
  ('The Power of Habit', 'Charles Duhigg', '9780812981605', 'Self-help', 'https://covers.openlibrary.org/b/isbn/9780812981605-L.jpg?default=false', 'Why do we do what we do, and how can we change it? Drawing on research and real cases, Charles Duhigg explains the loop of cue, routine and reward behind every habit.', 2, 2, UTC_TIMESTAMP() - INTERVAL 10 MINUTE, UTC_TIMESTAMP() - INTERVAL 10 MINUTE),
  ('Clean Code', 'Robert C. Martin', '9780132350884', 'Technology', 'https://covers.openlibrary.org/b/isbn/9780132350884-L.jpg?default=false', 'A working programmer''s handbook on writing code that others can read and maintain. Full of examples of turning messy code into clear code, with the reasoning behind each change.', 3, 3, UTC_TIMESTAMP() - INTERVAL 47 MINUTE, UTC_TIMESTAMP() - INTERVAL 47 MINUTE),
  ('The Pragmatic Programmer', 'Andrew Hunt', '9780135957059', 'Technology', 'https://covers.openlibrary.org/b/isbn/9780135957059-L.jpg?default=false', 'Practical advice for software developers at any stage, from keeping your knowledge up to date to writing flexible code. Short topics you can read in any order and apply the same day.', 3, 3, UTC_TIMESTAMP() - INTERVAL 13 MINUTE, UTC_TIMESTAMP() - INTERVAL 13 MINUTE),
  ('Design Patterns', 'Erich Gamma', '9780201633610', 'Technology', 'https://covers.openlibrary.org/b/isbn/9780201633610-L.jpg?default=false', 'The classic catalogue of twenty-three reusable solutions to common problems in object-oriented design. The book that gave programmers a shared vocabulary for how software fits together.', 2, 2, UTC_TIMESTAMP() - INTERVAL 50 MINUTE, UTC_TIMESTAMP() - INTERVAL 50 MINUTE),
  ('Refactoring', 'Martin Fowler', '9780134757599', 'Technology', 'https://covers.openlibrary.org/b/isbn/9780134757599-L.jpg?default=false', 'How to improve the design of existing code without changing what it does. Martin Fowler explains when to refactor and walks through a catalogue of small, safe steps.', 2, 2, UTC_TIMESTAMP() - INTERVAL 16 MINUTE, UTC_TIMESTAMP() - INTERVAL 16 MINUTE),
