  ('The Alchemist', 'Paulo Coelho', '9780062315007', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9780062315007-L.jpg?default=false', 'Santiago, a young Andalusian shepherd, dreams of treasure near the Egyptian pyramids and sets off to find it. A simple fable about following your dreams and reading the signs along the way.', 5, 5, UTC_TIMESTAMP() - INTERVAL 22 MINUTE, UTC_TIMESTAMP() - INTERVAL 22 MINUTE),
  ('The Kite Runner', 'Khaled Hosseini', '9781594631931', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9781594631931-L.jpg?default=false', 'Amir and Hassan grow up together in Kabul until one winter afternoon divides them for good. Years later, living in America, Amir is offered a chance to put things right.', 3, 3, UTC_TIMESTAMP() - INTERVAL 59 MINUTE, UTC_TIMESTAMP() - INTERVAL 59 MINUTE),
  ('A Thousand Splendid Suns', 'Khaled Hosseini', '9781594483851', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9781594483851-L.jpg?default=false', 'Mariam and Laila, born a generation apart, are thrown together as wives of the same man in war-torn Kabul. Their unlikely friendship becomes the thing that keeps them both alive.', 2, 2, UTC_TIMESTAMP() - INTERVAL 25 MINUTE, UTC_TIMESTAMP() - INTERVAL 25 MINUTE),
  ('Life of Pi', 'Yann Martel', '9780156027328', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9780156027328-L.jpg?default=false', 'After a shipwreck, sixteen-year-old Pi Patel is adrift in the Pacific in a lifeboat. His only companion is a Bengal tiger. A story about survival, faith and how stories are told.', 3, 3, UTC_TIMESTAMP() - INTERVAL 62 MINUTE, UTC_TIMESTAMP() - INTERVAL 62 MINUTE),
  ('The Book Thief', 'Markus Zusak', '9780375842207', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9780375842207-L.jpg?default=false', 'In Nazi Germany, a foster child named Liesel steals books and shares them with her neighbours and the Jewish man hidden in her basement. The narrator, unusually, is Death.', 3, 3, UTC_TIMESTAMP() - INTERVAL 28 MINUTE, UTC_TIMESTAMP() - INTERVAL 28 MINUTE),
  ('Normal People', 'Sally Rooney', '9781984822185', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9781984822185-L.jpg?default=false', 'Connell and Marianne come from the same small Irish town but very different worlds. From school to university they keep drifting apart and back together, never quite saying what they mean.', 2, 0, UTC_TIMESTAMP() - INTERVAL 65 MINUTE, UTC_TIMESTAMP() - INTERVAL 65 MINUTE),
  ('Where the Crawdads Sing', 'Delia Owens', '9780735219090', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9780735219090-L.jpg?default=false', 'Abandoned as a child, Kya grows up alone in the marshes of North Carolina. When a local man is found dead, the town turns on the girl it never accepted.', 3, 3, UTC_TIMESTAMP() - INTERVAL 31 MINUTE, UTC_TIMESTAMP() - INTERVAL 31 MINUTE),
  ('The Midnight Library', 'Matt Haig', '9780525559474', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9780525559474-L.jpg?default=false', 'Between life and death there is a library, and each book on its shelves is a life Nora Seed could have lived. She is given the chance to try them and find out what makes a life worth living.', 3, 3, UTC_TIMESTAMP() - INTERVAL 68 MINUTE, UTC_TIMESTAMP() - INTERVAL 68 MINUTE),
  ('The Seven Moons of Maali Almeida', 'Shehan Karunatilaka', '9781324064824', 'Fiction', 'https://covers.openlibrary.org/b/isbn/9781324064824-L.jpg?default=false', 'A war photographer wakes up dead in a chaotic afterlife in 1990 Colombo. He has seven moons to find out who killed him and to lead someone to the photographs that could expose the truth of Sri Lanka''s civil war.', 2, 2, UTC_TIMESTAMP() - INTERVAL 34 MINUTE, UTC_TIMESTAMP() - INTERVAL 34 MINUTE);
