-- Demo catalogue for local development: REPLACES every book, category, author, curated list and
-- favourite in the inventory database with a set of real titles, with descriptions.
-- Covers and author portraits are links to Open Library.
--
-- Run it against the local inventory database only, then restart the inventory service so it
-- recreates the starter lists:
--
--   docker exec -i readingpal-mysql mysql -uroot -p"$MYSQL_ROOT_PASSWORD" --default-character-set=utf8mb4 ReadingPal_inventory < infrastructure/mysql/seed-demo-catalogue.sql
--   docker compose restart inventory-service
--
-- Rows are deleted rather than truncated so new books get fresh IDs: old reservations and loans in
-- the lending database keep pointing at IDs that no longer exist instead of at the wrong book.

SET NAMES utf8mb4;
START TRANSACTION;

DELETE FROM FavouriteBooks;
DELETE FROM CuratedListItems;
DELETE FROM CuratedLists;
DELETE FROM Authors;
DELETE FROM BookCheckouts;
DELETE FROM Books;
DELETE FROM Genres;


-- Authors without a portrait on Open Library are left without one; the site shows their initial instead.

-- CreatedAt is staggered so 'newest first' mixes the categories. Three titles are out of stock on purpose.

COMMIT;
